// Native image generation — job execution tokens.
//
// Why this exists: transition_generation_job runs as the job's owner (the
// server uses the user-JWT client, so RLS applies), which means nothing
// distinguishes "the server executor marking a job failed after OpenAI
// errored" from "the user calling the RPC directly through PostgREST to
// force their own running job into a failed state". The latter wastes the
// in-flight provider call and games the refund path.
//
// The fix is a per-job, database-minted `execution_token` (a random byte
// string generated by the job-creation RPC). The column is revoked from
// anon/authenticated SELECT, so the only place the token ever appears is
// the create_generation_job(s) return value — which the server route sees
// and the browser never does. Terminal/execution transitions
// (running/succeeded/failed) require the token; cancellation stays
// token-free so users keep legitimate cancellation.
//
// The server must present the token again in later requests (/run, polling
// recovery), so it persists the token inside the session's plan_json —
// encrypted with GENERATION_PLAN_SECRET, because plan_json is readable by
// the owner. A user can read or overwrite the blob but cannot decrypt or
// forge it; overwriting only breaks their own job.

import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";

function keyFromSecret(secret: string): Buffer {
  return createHash("sha256").update(secret, "utf8").digest();
}

/** AES-256-GCM; output is base64url(iv | authTag | ciphertext). */
export function encryptExecutionToken(token: string, secret: string): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", keyFromSecret(secret), iv);
  const ciphertext = Buffer.concat([cipher.update(token, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, tag, ciphertext]).toString("base64url");
}

/** Throws on tampering or a wrong secret — callers treat that as "no token". */
export function decryptExecutionToken(blob: string, secret: string): string {
  const raw = Buffer.from(blob, "base64url");
  if (raw.length < 12 + 16 + 1) throw new Error("invalid execution token blob");
  const iv = raw.subarray(0, 12);
  const tag = raw.subarray(12, 28);
  const ciphertext = raw.subarray(28);
  const decipher = createDecipheriv("aes-256-gcm", keyFromSecret(secret), iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");
}

/**
 * plan_json shape: executionTokensEnc maps a job's idempotency key to its
 * encrypted execution token. Keyed by idempotency key (not job id) because
 * the keys are what jobs.ts knows aligns children to jobs at creation time.
 */
export type ExecutionTokenMap = Record<string, string>;

export function encryptExecutionTokenMap(
  tokensByIdempotencyKey: Record<string, string>,
  secret: string,
): ExecutionTokenMap {
  const out: ExecutionTokenMap = {};
  for (const [key, token] of Object.entries(tokensByIdempotencyKey)) {
    out[key] = encryptExecutionToken(token, secret);
  }
  return out;
}

/**
 * Read and decrypt one job's execution token from a stored plan_json.
 * Returns null when absent (pre-migration sessions), malformed, or
 * undecryptable — callers then fall back to the legacy token-less path,
 * which works until the Step 3 migration is applied and is denied after.
 */
export function extractExecutionToken(
  planJson: unknown,
  idempotencyKey: string,
  secret: string,
): string | null {
  if (!planJson || typeof planJson !== "object") return null;
  const map = (planJson as { executionTokensEnc?: unknown }).executionTokensEnc;
  if (!map || typeof map !== "object") return null;
  const blob = (map as Record<string, unknown>)[idempotencyKey];
  if (typeof blob !== "string" || blob.length === 0) return null;
  try {
    return decryptExecutionToken(blob, secret);
  } catch {
    return null;
  }
}
